import{_ as d,o as a,c as r,a as e}from"./chunks/framework.Ld7uezS_.js";const f=JSON.parse('{"title":"只读训练总览","description":"","frontmatter":{},"headers":[],"relativePath":"training.md","filePath":"training.md","lastUpdated":1787284307000}'),i={name:"training.md"};function l(o,t,h,n,s,c){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="只读训练总览" tabindex="-1">只读训练总览 <a class="header-anchor" href="#只读训练总览" aria-label="Permalink to &quot;只读训练总览&quot;">​</a></h1><blockquote><p><strong>只读训练：答案与解析已展开，无需作答或提交。</strong></p></blockquote><p>本站训练系统的目标是让学员通过“看题—看答案—看解析—回看知识页”完成学习，不设置答题框、提交按钮、自动判分或错题统计。</p><h2 id="先说明题源" tabindex="-1">先说明题源 <a class="header-anchor" href="#先说明题源" aria-label="Permalink to &quot;先说明题源&quot;">​</a></h2><p>本站不会把未经核验的网络题目写成“官方真题”。每道题都显示题源标签：</p><ul><li><strong>官方真题/历年原题</strong>：只有在能核验官方授权来源、年份、地区和试卷信息时才使用；当前站点不凭网络转载内容冒充此类题源。</li><li><strong>官方公开样题</strong>：由官方机构公开发布并可访问，页面显示原链接和发布日期。</li><li><strong>原创训练题</strong>：编辑组依据职业标准、现行法律法规和消防技术标准编写，不暗示曾在考试中出现。</li><li><strong>改编训练题</strong>：基于可访问公开材料改写，保留原始来源并标注改动。</li></ul><p>没有可核验凭据的题目，一律不标“真题”“原题”“押题”或“命中率”。</p><h2 id="推荐阅读顺序" tabindex="-1">推荐阅读顺序 <a class="header-anchor" href="#推荐阅读顺序" aria-label="Permalink to &quot;推荐阅读顺序&quot;">​</a></h2><p>如果你是第一次学习，建议严格按下面的七步走完一轮：</p><ol><li><strong>先读导学</strong>：完成<a href="/beginner-guide">零基础导学</a>，建立建筑消防系统整体地图；</li><li><strong>再读理论</strong>：按理论 1—10 章顺序学习，不要一开始只刷题；</li><li><strong>先读操作前置课</strong>：在进入设备项目卡前，学习<a href="/skill/02-operation">设施操作</a>中的任务类型、对象四层、区域定位、完成标准和“五问确认法”；</li><li><strong>再读设备</strong>：依次学习<a href="/skill/alarm-system">报警系统</a>、<a href="/skill/water-system">水系统</a>、<a href="/skill/other-facilities">其他消防设施</a>项目卡；</li><li><strong>再读四项技能</strong>：按“监控基础 → 操作 → 保养 → 维修 → 检测”阅读；检测维修保养方向把后四项作为主线；</li><li><strong>最后看训练</strong>：先看 L1，再看 L2，最后看 L3 和综合闭环场景；答案已经展开，不需要输入；</li><li><strong>回看不会的知识</strong>：每道题都通过“关联知识页”回到原理，不要只记题目结论。</li></ol><h3 id="每次学习后的三分钟自检" tabindex="-1">每次学习后的三分钟自检 <a class="header-anchor" href="#每次学习后的三分钟自检" aria-label="Permalink to &quot;每次学习后的三分钟自检&quot;">​</a></h3><p>合上当前页面后，用自己的话回答：</p><ul><li>这个设备或概念解决什么问题？</li><li>它正常时、异常时分别有什么表现？</li><li>操作/保养/维修/检测中，我现在学的是哪一种工作？</li><li>我需要观察哪些显示、动作或反馈？</li><li>结束时要恢复什么、记录什么？</li></ul><p>五个问题中有两个以上答不上来，就回到对应知识页重新读，而不是直接跳到下一张题。</p><h3 id="训练页内回看顺序" tabindex="-1">训练页内回看顺序 <a class="header-anchor" href="#训练页内回看顺序" aria-label="Permalink to &quot;训练页内回看顺序&quot;">​</a></h3><p>完成第一轮课程后，在本页训练时按以下顺序回看：</p><ol><li><a href="/training-theory">理论训练</a>：按 L1 识记 → L2 理解辨析 → L3 场景应用阅读；</li><li><a href="/training-skill">技能训练</a>：按任务目标、操作前确认、标准步骤、反馈恢复和安全边界阅读；</li><li>返回对应<a href="/theory/01-professional-ethics">理论知识页</a>或<a href="/skill/01-monitoring">技能知识页</a>复习原理；</li><li>最后查看<a href="/training-labels">题源与标记说明</a>，理解来源和版本边界。</li></ol><h2 id="十章理论与技能项目关联索引" tabindex="-1">十章理论与技能项目关联索引 <a class="header-anchor" href="#十章理论与技能项目关联索引" aria-label="Permalink to &quot;十章理论与技能项目关联索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>理论章节</th><th>设备原理关键词</th><th>关联技能项目</th><th>推荐训练题</th></tr></thead><tbody><tr><td>1. 职业道德</td><td>如实、守规、复核、报告</td><td>四项技能记录与恢复</td><td>T01、T15、T28；S01、S06、S23</td></tr><tr><td>2. 消防工作概述</td><td>单位责任、岗位协同、异常升级</td><td>操作、保养、维修、检测责任边界</td><td>T02、T16、T29；S01、S25</td></tr><tr><td>3. 燃烧和火灾</td><td>燃烧条件、烟气、灭火介质</td><td>初起处置、器材保养、检测安全</td><td>T03-T04、T30、T34；S06、S25、S43</td></tr><tr><td>4. 建筑防火</td><td>防火分区、防烟分区、防火间距、耐火极限、耐火等级、疏散与防火分隔</td><td>风阀、卷帘、门及反馈恢复</td><td>T20-T21、T31、T38-T39；S21、S38-S39、S46</td></tr><tr><td>5. 电气消防</td><td>主备电、回路、接地、保护</td><td>电气操作、维修、检测与隔离</td><td>T06、T22、T32；S08、S26、S30、S47</td></tr><tr><td>6. 消防设施</td><td>探测—报警—控制—动作—反馈—恢复；回路/地址定位；水力证据链与五项检测结果</td><td>泵组、报警、联动、保养、维修、检测</td><td>T08-T10、T23-T24、T33；S02、S19-S22、S26-S49</td></tr><tr><td>7. 初起火灾处置</td><td>报警、疏散、现场保护、复燃</td><td>监控、联动测试、停用防护</td><td>T07、T11、T17、T34；S01、S21、S25</td></tr><tr><td>8. 计算机基础</td><td>控制器界面、日志、通信</td><td>查询、记录、故障信息和复测留痕</td><td>T13、T18、T25、T35；S01、S07、S09、S31</td></tr><tr><td>9. 法律法规与技术标准</td><td>依据层级、版本、权限、判定</td><td>四项技能方法选择与结论边界</td><td>T05、T12、T26、T36；S04、S05、S11-S14</td></tr><tr><td>10. 安全生产与职业健康</td><td>断电、验电、隔离、监护、清场</td><td>四项技能前置、过程和恢复安全</td><td>T14、T19、T27、T37；S04、S07-S10、S12、S21</td></tr></tbody></table><blockquote><p>以上题号是本站原创训练题/场景题的导航编号，不是官方题库、真题或现场评分表。若题卡、设备说明书、检测方案或鉴定站要求不一致，以适用现场依据为准。</p></blockquote><h3 id="综合复习路径" tabindex="-1">综合复习路径 <a class="header-anchor" href="#综合复习路径" aria-label="Permalink to &quot;综合复习路径&quot;">​</a></h3><ul><li>第一遍按十章理论顺序复习，每章完成一张 T 题并写出一个设备原理因果句；</li><li>第二遍按报警、水系统、其他设施横向复习，分别复述组成、动作、反馈、故障和恢复；</li><li>第三遍按操作→保养→维修→检测纵向复习，用同一设备比较四种工作的目的、证据和记录；</li><li>第四遍做 S23-S25 综合闭环，再按问题回看 S26-S49 设备专项；</li><li>第五遍复核标准、方案、说明书和地方评分表，清理所有未经依据支持的固定数值或操作结论。</li></ul><h2 id="训练模块地图" tabindex="-1">训练模块地图 <a class="header-anchor" href="#训练模块地图" aria-label="Permalink to &quot;训练模块地图&quot;">​</a></h2><h3 id="理论训练" tabindex="-1">理论训练 <a class="header-anchor" href="#理论训练" aria-label="Permalink to &quot;理论训练&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模块</th><th>训练入口</th><th>首批重点</th></tr></thead><tbody><tr><td>1. 职业道德</td><td><a href="/theory/01-professional-ethics">知识页</a></td><td>职业守则、岗位责任</td></tr><tr><td>2. 消防工作概述</td><td><a href="/theory/02-fire-service-overview">知识页</a></td><td>消防方针、单位职责</td></tr><tr><td>3. 燃烧和火灾</td><td><a href="/theory/03-combustion-fire">知识页</a></td><td>燃烧条件、火灾分类</td></tr><tr><td>4. 建筑防火</td><td><a href="/theory/04-building-fire">知识页</a></td><td>防火分隔、疏散与现行规范</td></tr><tr><td>5. 电气消防</td><td><a href="/theory/05-electrical-fire">知识页</a></td><td>过载、短路、保护边界</td></tr><tr><td>6. 消防设施</td><td><a href="/theory/06-fire-facilities">知识页</a></td><td>报警、联动、反馈、恢复</td></tr><tr><td>7. 初起火灾处置</td><td><a href="/theory/07-initial-fire">知识页</a></td><td>报警、疏散、灭火安全</td></tr><tr><td>8. 计算机基础</td><td><a href="/theory/08-computer">知识页</a></td><td>值班记录、信息安全</td></tr><tr><td>9. 法律法规与标准</td><td><a href="/theory/09-laws-standards">知识页</a></td><td>版本核验、适用边界</td></tr><tr><td>10. 安全生产与职业健康</td><td><a href="/theory/10-safety-health">知识页</a></td><td>危险源、隔离、监护</td></tr></tbody></table><h3 id="技能训练" tabindex="-1">技能训练 <a class="header-anchor" href="#技能训练" aria-label="Permalink to &quot;技能训练&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职业功能</th><th>训练入口</th><th>阅读重点</th></tr></thead><tbody><tr><td>设施监控</td><td><a href="/skill/01-monitoring">知识页</a></td><td>识别、记录、报告、恢复</td></tr><tr><td>设施操作</td><td><a href="/skill/02-operation">知识页</a></td><td>任务识别、对象/区域确认、控制方式、动作、反馈和恢复</td></tr><tr><td>设施保养</td><td><a href="/skill/03-maintenance">知识页</a></td><td>外观、连接、状态、功能、记录</td></tr><tr><td>设施维修</td><td><a href="/skill/04-repair">知识页</a></td><td>判断、隔离、处理、验证</td></tr><tr><td>设施检测</td><td><a href="/skill/05-detection">知识页</a></td><td>输入、显示、动作、反馈、恢复</td></tr></tbody></table><blockquote><p>当前训练卡集中在理论与技能训练页中，模块地图先帮助学员定位学习范围；后续新增题卡时，必须挂到对应模块和知识页，不能建立脱离课程的“散题页”。</p></blockquote><h2 id="按你的方向学习" tabindex="-1">按你的方向学习 <a class="header-anchor" href="#按你的方向学习" aria-label="Permalink to &quot;按你的方向学习&quot;">​</a></h2><p>你选择的是 <strong>消防设施检测维修保养</strong>，训练时不要平均浏览所有内容，建议按下面顺序阅读：</p><ol><li><a href="/training-theory">理论训练</a>：先掌握消防设施、报警联动、电气安全、法规和记录基础；</li><li><a href="/training-skill">技能训练</a>：先看监控和操作，再重点看保养、维修、检测；</li><li>每看完一张技能卡，都追问“依据是什么、反馈在哪里、恢复是否完成、记录写什么”；</li><li>最后回到<a href="/skill-roadmap">技能考核路线图</a>，按四个核心职业功能复述完整闭环。</li></ol><div class="warning custom-block"><p class="custom-block-title">不要把训练题当成评分表</p><p>本站训练题用于理解和记忆，不代表你的鉴定站现场原题或完整评分表。具体考核项目、评分点、操作顺序和关键技能判定，必须以报考地最新公告、现场评分表和设备条件为准。</p></div><h2 id="难度标记" tabindex="-1">难度标记 <a class="header-anchor" href="#难度标记" aria-label="Permalink to &quot;难度标记&quot;">​</a></h2><table tabindex="0"><thead><tr><th>标记</th><th>含义</th><th>适合的学习阶段</th></tr></thead><tbody><tr><td>L1</td><td>识记：定义、构成、基本用途</td><td>第一次学习</td></tr><tr><td>L2</td><td>理解/辨析：条件、关系、易混概念</td><td>理论复习</td></tr><tr><td>L3</td><td>应用/故障场景：顺序、异常和多条件判断</td><td>考前强化与技能衔接</td></tr></tbody></table><h2 id="训练卡固定结构" tabindex="-1">训练卡固定结构 <a class="header-anchor" href="#训练卡固定结构" aria-label="Permalink to &quot;训练卡固定结构&quot;">​</a></h2><p>每张训练卡都直接显示：</p><ul><li>题型和难度；</li><li>题源标签、来源、发布日期/版本；</li><li>题干和选项；</li><li>正确答案；</li><li>逐项解析和错误选项边界；</li><li>核心知识点；</li><li>关联知识页和标准依据；</li><li>技能题的安全提示、反馈信号和恢复记录。</li></ul><blockquote><p>训练题不等同于实际考试。具体题量、题型、技能项目、分值、评分门槛和考务安排，以报考地消防行业职业技能鉴定站最新公告、准考证和现场评分表为准。</p></blockquote>',38)])])}const u=d(i,[["render",l]]);export{f as __pageData,u as default};
